package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public final class BoundedWallHistoryTest {
 public static void main(String[] args)throws Exception{Path snapshots=Paths.get(args[0]),fixtures=Paths.get(args[1]);int checks=0,owners=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(snapshots,"owner-*.nwh")){for(Path file:files){String serial=file.getFileName().toString().substring(6).replace(".nwh","");NativeWallHistory history=new NativeWallHistory(Files.readAllBytes(file));ByteBuffer proof=ByteBuffer.wrap(Files.readAllBytes(fixtures.resolve("owner-"+serial+".nrp"))).order(ByteOrder.LITTLE_ENDIAN);NativeWallHistory.Samples samples=history.samples(proof.getLong(24),proof.getLong(48),(int)proof.getLong(64));byte[] original=Files.readAllBytes(fixtures.resolve("full-native-"+serial+".bin"));for(int cell=0;cell<38400;cell++){if(proof.get(80+cell)!=2)continue;int asset=samples.asset(cell),offset=samples.offset(cell);if(asset<0||offset<0||history.asset(asset).get(offset)!=original[cell]||samples.refresh(cell)!=Integer.toUnsignedLong(proof.getInt(38480+cell*4)))throw new AssertionError("Bounded history differs from original owner");checks++;}owners++;}}if(owners!=13||checks!=299970)throw new AssertionError("Incomplete bounded fixtures");System.out.println("PASS_BOUNDED_WALL_JAVA owners="+owners+" source_and_writer_checks="+checks);}
}
